INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (222, 1, 'printf 는 줄바꿈을 넣지 않는다', '`printf ''a''` 와 `printf ''a\\n''` 의 출력은 어떻게 다를까요?', 'echo 와 달리 자동으로 줄을 바꾸지 않아요.', NULL, NULL, '[]', 'choice', '["앞과 뒤 모두 `a` 와 줄바꿈을 출력하고 `\\\\n` 은 있어도 없어도 결과가 같다", "앞은 `a` 와 줄바꿈을 출력하고, 뒤는 줄바꿈을 두 번 출력한다", "앞은 `a` 만 출력하고 줄바꿈이 없고, 뒤는 `a` 와 줄바꿈까지 출력한다", "앞은 아무것도 출력하지 않고 `\\\\n` 이 있어야만 `a` 가 보인다"]', 2, '`echo` 는 끝에 줄바꿈을 자동으로 붙이지만 `printf` 는 서식에 적은 것만 출력합니다.', NULL, NULL, NULL, NULL),
  (222, 2, '서식 되풀이', '`printf ''%s\\n'' a b c` 는 무엇을 출력할까요?', '인자가 남으면 서식을 다시 써요.', NULL, NULL, '[]', 'choice', '["`a` 만 출력되고 나머지 인자 `b` 와 `c` 는 무시된다", "`a`, `b`, `c` 가 한 줄씩 세 줄로 출력된다", "`a b c` 가 한 줄로 합쳐져서 줄바꿈 한 번과 함께 출력된다", "오류가 나서 아무것도 출력되지 않고 서식 하나에 인자는 하나만 줄 수 있다"]', 1, '인자가 서식의 자리 수보다 많으면 모두 쓸 때까지 서식을 되풀이합니다.', NULL, NULL, NULL, NULL),
  (222, 3, '자리가 남는 서식', '`printf ''%s %s\\n'' a b c` 는 몇 줄을 출력하고 마지막 줄은 어떻게 보일까요?', '둘째 줄에서는 인자가 모자라요.', NULL, NULL, '[]', 'choice', '["두 줄이 출력되고 마지막 줄은 `c ` 로 모자란 자리가 빈 문자열이 된다", "두 줄이 출력되고 마지막 줄은 `c c` 로 앞의 인자가 한 번 더 쓰인다", "한 줄이 출력되고 `c` 는 자리가 없어서 버려진다", "오류가 나서 첫 줄 `a b` 만 출력하고 `c` 에서 멈춘다"]', 0, '빈 자리는 문자열이면 빈 문자열, 숫자면 `0` 으로 채워집니다.', NULL, NULL, NULL, NULL),
  (222, 4, '%5s 와 %-5s', '`printf ''%5s|\\n'' ab` 와 `printf ''%-5s|\\n'' ab` 는 각각 무엇을 출력할까요?', '숫자는 너비이고 - 는 왼쪽 정렬이에요.', NULL, NULL, '[]', 'choice', '["앞은 `ab   |` 로 왼쪽 정렬, 뒤는 `   ab|` 로 오른쪽 정렬이다", "둘 다 `ab|` 로 출력되고 너비는 숫자에만 적용된다", "앞은 `   ab|` 이고 뒤는 `-   ab|` 로 `-` 가 글자로 그대로 출력된다", "앞은 `   ab|` 로 오른쪽 정렬, 뒤는 `ab   |` 로 왼쪽 정렬이다"]', 3, '너비보다 긴 글자는 잘리지 않고 그대로 출력됩니다.', NULL, NULL, NULL, NULL),
  (222, 5, '%.3s 로 자르기', '`printf ''%.3s\\n'' hello` 는 무엇을 출력할까요?', '점 뒤의 숫자는 글자 수의 한도예요.', NULL, NULL, '[]', 'choice', '["`hello` 를 그대로 출력한다. `.3` 은 소수에만 적용되고 문자열에는 쓸 수 없다", "`llo` 를 출력한다. 글자를 뒤에서부터 세어서 세 글자만 남긴다", "`hel` 만 출력한다. `%s` 에서 `.3` 은 최대 3글자를 뜻한다", "`hello` 뒤에 `000` 을 붙여서 모두 여덟 글자로 맞춰 출력한다"]', 2, '숫자에 `.2` 를 쓰면 `%.2f` 처럼 소수 자릿수가 됩니다.', NULL, NULL, NULL, NULL),
  (222, 6, '%05d', '`printf ''%05d\\n'' 42` 는 무엇을 출력할까요?', '0 은 빈칸을 0 으로 채워요.', NULL, NULL, '[]', 'choice', '["`42000` 을 출력한다. 너비 5 에 맞춰 뒤쪽을 `0` 으로 채워 넣는다", "`00042` 를 출력한다. 너비 5 에 맞춰 앞을 `0` 으로 채운다", "`   42` 를 출력한다. 앞쪽을 `0` 이 아니라 공백으로 채운다", "`42` 만 출력한다. `0` 은 `%d` 에서는 아무 뜻이 없어 무시된다"]', 1, '`%5d` 는 공백으로, `%05d` 는 `0` 으로 앞을 채웁니다.', NULL, NULL, NULL, NULL),
  (222, 7, '앞에 0 이 붙은 수', '`printf ''%d\\n'' 010` 은 무엇을 출력할까요? `08` 은 어떻게 될까요?', '앞의 0 은 8진수를 뜻해요.', NULL, NULL, '[]', 'choice', '["`010` 은 8진수로 읽어 `8` 을 출력하고, `08` 은 `invalid octal number` 오류가 난다", "`010` 은 그대로 `10` 을 출력하고, `08` 도 앞의 0 을 떼고 `8` 을 출력한다", "`010` 은 `10` 을 출력하고, `08` 은 `invalid octal number` 오류가 나서 멈춘다", "`010` 은 `8` 을 출력하고, `08` 은 `8` 을 출력해서 앞의 0 은 항상 무시된다"]', 0, '`printf ''%d\\n'' 0x1F` 처럼 `0x` 로 시작하면 16진수로 읽어 `31` 이 됩니다.', NULL, NULL, NULL, NULL),
  (222, 8, '%d 에 소수를 주면', '`printf ''%d\\n'' 3.7` 을 실행하면 어떻게 될까요?', '정수 서식에 소수를 넘겼어요.', NULL, NULL, '[]', 'choice', '["반올림해서 `4` 를 출력하고 오류 메시지 없이 종료 코드는 `0` 으로 끝나게 된다", "`3.7` 을 그대로 출력하고 오류 메시지 없이 종료 코드는 `0` 으로 끝난다", "아무것도 출력하지 않고 오류 메시지만 내며 종료 코드는 `2` 로 끝난다", "`invalid number` 오류를 내면서 `3` 을 출력하고 종료 코드는 `1` 이다"]', 3, '소수를 쓰려면 `%.1f` 처럼 `f` 서식을 씁니다.', NULL, NULL, NULL, NULL),
  (222, 9, '%b 와 %s', '`printf ''%s\\n'' ''a\\tb''` 와 `printf ''%b\\n'' ''a\\tb''` 는 각각 무엇을 출력할까요? (`\\t` 는 탭)', 'b 는 인자 속의 이스케이프를 풀어 줘요.', NULL, NULL, '[]', 'choice', '["앞은 탭으로 바꿔서, 뒤는 `a\\\\tb` 글자 그대로 출력한다", "둘 다 `\\\\t` 를 탭으로 바꿔서 출력하고 두 서식 사이에 차이는 없다", "앞은 `a\\\\tb` 글자 그대로, 뒤는 `\\\\t` 를 탭으로 바꿔서 출력한다", "둘 다 `a\\\\tb` 글자 그대로 출력하고 이스케이프는 서식 문자열에서만 풀린다"]', 2, '서식 문자열 자체에 쓴 `\\t` 는 `printf ''a\\tb\\n''` 처럼 항상 탭이 됩니다.', NULL, NULL, NULL, NULL),
  (222, 10, '% 글자 출력', '`printf ''100%\\n''` 을 실행하면 어떻게 될까요?', '% 는 서식의 시작이에요.', NULL, NULL, '[]', 'choice', '["`100%` 를 오류 없이 그대로 출력하고 줄바꿈도 정상으로 들어가서 한 줄이 된다", "`invalid format character` 오류가 나고 `%` 를 출력하려면 `%%` 로 써야 한다", "`100` 만 출력하고 `%` 와 뒤의 줄바꿈은 조용히 버려져서 줄이 이어진다", "`100` 과 `\\\\n` 글자를 그대로 이어서 출력하고 줄은 바뀌지 않으며 오류도 없다"]', 1, '`printf ''100%%\\n''` 은 `100%` 를 출력합니다.', NULL, NULL, NULL, NULL),
  (222, 11, 'seq 의 -w 와 감소', '`seq -w 8 10` 은 무엇을 출력하고, `seq 5 -1 1` 은 어떤 순서로 출력할까요?', '-w 는 너비를 맞춰요. 가운데 수는 증가분이에요.', NULL, NULL, '[]', 'choice', '["앞은 `08`, `09`, `10` 이고 뒤는 `5 4 3 2 1` 이다", "앞은 `8`, `9`, `10` 이고 뒤는 `1 2 3 4 5` 이다", "앞은 `08`, `09`, `10` 이고 뒤는 아무것도 출력하지 않는다", "앞은 `008`, `009`, `010` 이고 뒤는 `5 4 3 2 1` 이다"]', 0, '`seq 1 2 7` 은 `1 3 5 7` 이므로 가운데 수가 증가분입니다.', NULL, NULL, NULL, NULL),
  (222, 12, '끝이 시작보다 작을 때', '`seq 3 1` 은 무엇을 출력하고 종료 코드는 얼마일까요?', '증가분을 주지 않으면 1 씩 늘려요.', NULL, NULL, '[]', 'choice', '["`3 2 1` 을 출력하고 종료 코드는 `0` 이다", "오류 메시지를 출력하고 종료 코드는 `1` 이다", "`3` 만 출력하고 종료 코드는 `0` 이다", "아무것도 출력하지 않고 종료 코드는 `0` 이다"]', 3, '내려가려면 `seq 3 -1 1` 처럼 증가분을 음수로 줍니다.', NULL, NULL, NULL, NULL),
  (222, 13, 'shuf -n 은 중복 없이', '다섯 줄짜리 파일에 `shuf -n 10 파일` 을 실행하면 몇 줄이 나올까요?', '중복 없이 섞는 게 기본이에요.', NULL, NULL, '[]', 'choice', '["열 줄이 나온다. 모자란 다섯 줄은 이미 나온 줄을 다시 뽑아서 채운다", "다섯 줄이 나오지만 같은 줄이 두 번 이상 나올 수 있어서 빠지는 줄도 생긴다", "다섯 줄이 나온다. 있는 줄만 한 번씩 섞어서 출력하고 모자란 만큼 채우지 않는다", "오류가 나서 아무것도 출력하지 않고 `-n` 값은 파일의 줄 수 이하여야만 한다"]', 2, '같은 줄을 다시 뽑으려면 `-r` 을 줍니다. `shuf -r -n 5 -i 1-2` 는 5줄을 출력합니다.', NULL, NULL, NULL, NULL),
  (222, 14, 'shuf -e', '`shuf -e a b c` 는 무엇을 출력할까요?', '-e 는 인자를 줄로 봐요.', NULL, NULL, '[]', 'choice', '["`a`, `b`, `c` 중에서 무작위로 하나만 골라서 한 줄로만 출력한다", "`a`, `b`, `c` 를 모두 한 번씩 무작위 순서로 한 줄씩 출력한다", "`a b c` 를 한 줄에 입력한 순서 그대로 공백으로 묶어서 출력한다", "입력 파일이 없으므로 표준 입력에서 줄이 들어오기를 기다리며 멈춘다"]', 1, '`shuf -i 1-5` 는 `1` 부터 `5` 까지를 무작위 순서로 한 번씩 출력합니다.', NULL, NULL, NULL, NULL),
  (222, 15, '문자열 서식', '`printf` 에서 **문자열을 출력하는** 서식 글자를 채우세요.', '"string"의 첫 글자예요.', NULL, NULL, '[]', 'fill', '["d", "c", "f", "s"]', NULL, '`%c` 는 첫 글자 하나만 출력합니다.', '[3]', 'printf ''%{0}\\n'' abc', NULL, NULL),
  (222, 16, '정수 서식', '`printf` 에서 **10진 정수를 출력하는** 서식 글자를 채우세요.', '"decimal"의 첫 글자예요.', NULL, NULL, '[]', 'fill', '["d", "s", "x", "f"]', NULL, '소수는 `%f` 로 출력합니다.', '[0]', 'printf ''%{0}\\n'' 42', NULL, NULL),
  (222, 17, '16진수로 출력', '`printf` 에서 **정수를 16진수 소문자로 출력하는** 서식 글자를 채우세요.', '"hexadecimal"의 x 예요.', NULL, NULL, '[]', 'fill', '["o", "x", "d", "h"]', NULL, '`255` 를 `%x` 로 출력하면 `ff` 입니다.', '[1]', 'printf ''%{0}\\n'' 255', NULL, NULL),
  (222, 18, '소수 둘째 자리', '`printf` 에서 **소수를 소수점 아래 두 자리로 출력하는** 서식의 마지막 글자를 채우세요.', '"float"의 첫 글자예요.', NULL, NULL, '[]', 'fill', '["d", "s", "f", "e"]', NULL, '`3.14159` 는 `3.14` 로 출력됩니다.', '[2]', 'printf ''%.2{0}\\n'' 3.14159', NULL, NULL),
  (222, 19, '왼쪽 정렬', '`printf` 에서 **너비 안에서 왼쪽으로 정렬하는** 기호를 채우세요.', '"빼기"와 같은 모양이에요.', NULL, NULL, '[]', 'fill', '["+", "0", "#", "-"]', NULL, '기호 없이 `%5s` 는 오른쪽 정렬입니다.', '[3]', 'printf ''%{0}5s|\\n'' ab', NULL, NULL),
  (222, 20, '0 으로 채우기', '`printf` 에서 **너비에 맞춰 앞을 0 으로 채우는** 기호를 채우세요.', '숫자 영이에요.', NULL, NULL, '[]', 'fill', '["0", "-", "+", "."]', NULL, '`%05d` 는 `42` 를 `00042` 로 출력합니다.', '[0]', 'printf ''%{0}5d\\n'' 42', NULL, NULL),
  (222, 21, '퍼센트 글자 출력', '`printf` 에서 **`%` 글자 자체를 출력하려면** 서식에 무엇을 쓰는지 채우세요.', '두 번 써요.', NULL, NULL, '[]', 'fill', '["\\\\%", "%%", "%c", "%p"]', NULL, '`%` 하나만 쓰면 서식의 시작으로 읽힙니다.', '[1]', 'printf ''100{0}\\n''', NULL, NULL),
  (222, 22, 'seq 너비 맞추기', '`seq` 에서 **가장 큰 수의 자릿수에 맞춰 앞을 0 으로 채우는** 옵션을 채우세요.', '"width"의 첫 글자예요.', NULL, NULL, '[]', 'fill', '["s", "f", "w", "t"]', NULL, '`08`, `09`, `10` 이 출력됩니다.', '[2]', 'seq -{0} 8 10', NULL, NULL),
  (222, 23, 'seq 구분자', '`seq` 에서 **줄바꿈 대신 쓸 구분자를 정하는** 옵션을 채우세요.', '"separator"의 첫 글자예요.', NULL, NULL, '[]', 'fill', '["w", "f", "n", "s"]', NULL, '`1,2,3` 이 출력됩니다.', '[3]', 'seq -{0}, 1 3', NULL, NULL),
  (222, 24, 'shuf 줄 수', '`shuf` 에서 **출력할 줄 수를 정하는** 옵션을 채우세요.', '"number"의 첫 글자예요.', NULL, NULL, '[]', 'fill', '["n", "c", "l", "k"]', NULL, '중복 없이 뽑으므로 파일의 줄 수가 한도입니다.', '[0]', 'shuf -{0} 2 file', NULL, NULL),
  (222, 25, 'shuf 인자 섞기', '`shuf` 에서 **인자로 준 값을 줄처럼 섞는** 옵션을 채우세요.', '"echo"의 첫 글자예요.', NULL, NULL, '[]', 'fill', '["a", "e", "s", "r"]', NULL, '파일 없이 값 몇 개를 바로 섞을 때 씁니다.', '[1]', 'shuf -{0} a b c', NULL, NULL),
  (222, 26, '정렬 서식 확인', '`printf` 의 너비와 채우기 서식을 하나씩 확인하는 순서입니다. 순서에 맞게 놓아 보세요.', '오른쪽 → 왼쪽 → 0 채우기 → 소수 순서예요.', NULL, NULL, '[]', 'order', '["`printf ''%.2f\\\\n'' 3.14159` 로 `3.14` 가 나오는지 확인한다", "`printf ''%05d\\\\n'' 42` 로 `00042` 가 나오는지 확인한다", "`printf ''%5s|\\\\n'' ab` 로 `   ab|` 가 나오는지 확인한다", "`printf ''%-5s|\\\\n'' ab` 로 `ab   |` 가 나오는지 확인한다"]', NULL, '너비보다 긴 글자는 잘리지 않습니다.', '[2, 3, 1, 0]', NULL, NULL, NULL),
  (222, 27, '번호 붙은 이름 만들기', '번호가 붙은 이름을 만드는 방법을 확인하는 순서입니다. 순서에 맞게 놓아 보세요.', 'seq → -w → printf → 서식 되풀이 순서예요.', NULL, NULL, '[]', 'order', '["`printf ''f%02d.txt\\\\n'' 1 2 3` 으로 `f01.txt` 부터 `f03.txt` 까지 나오는지 확인한다", "`printf ''%s=%d\\\\n'' a 1 b 2` 로 서식이 두 번 쓰여 두 줄이 나오는지 확인한다", "`seq -w 8 10` 으로 `08`, `09`, `10` 이 나오는지 확인한다", "`seq 8 10` 으로 `8`, `9`, `10` 이 나오는지 확인한다"]', NULL, '`seq -w 1 100` 은 `001`, `002` 처럼 세 자리로 맞춥니다.', '[3, 2, 0, 1]', NULL, NULL, NULL),
  (222, 28, 'shuf 로 섞기 확인', '`shuf` 가 줄을 섞기만 한다는 것을 확인하는 순서입니다. 순서에 맞게 놓아 보세요.', '만들기 → 전체 → 일부 → 비교 순서예요.', NULL, NULL, '[]', 'order', '["`shuf -n 2 n | wc -l` 로 `2` 줄만 나오는지 확인한다", "`seq 1 5 > n` 으로 다섯 줄짜리 파일을 만든다", "`shuf n | sort -n | cmp - n` 으로 섞어도 줄의 집합이 같은지 확인한다", "`shuf n | wc -l` 로 줄 수가 `5` 로 그대로인지 확인한다"]', NULL, '`cmp` 는 같으면 아무것도 출력하지 않습니다.', '[1, 3, 0, 2]', NULL, NULL, NULL),
  (222, 29, '서식 되풀이 확인', '인자 수에 따라 서식이 되풀이되는 것을 확인하는 순서입니다. 순서에 맞게 놓아 보세요.', '하나 → 여럿 → 모자람 → 줄 수 순서예요.', NULL, NULL, '[]', 'order', '["`printf ''%s\\\\n'' a b c` 로 세 줄이 나오는지 확인한다", "그 출력을 `wc -l` 로 세어 `2` 줄인지 확인한다", "`printf ''%s\\\\n'' a` 로 `a` 한 줄이 나오는지 확인한다", "`printf ''%s %s\\\\n'' a b c` 로 마지막 줄이 `c ` 로 나오는지 확인한다"]', NULL, '모자란 숫자 자리는 `0` 으로 채워집니다.', '[2, 0, 3, 1]', NULL, NULL, NULL);
